#!/usr/bin/env python3
"""Prints the generated parts of ../PROOF.bend (deep patterns on words and
lists that are tedious to write by hand); PROOF.bend holds them after
"# generated by gen/proof_lemmas.py (PART)" lines. Run it and paste a part:

    proof_lemmas.py words | chunks | groups | lens | starts
"""
import sys


def u32_pat(k, last="r"):
    s = last
    for i in range(k - 1, -1, -1):
        s = "WCon{c%d, %s}" % (i, s)
    return "U32{%s}" % s


def words():
    out = []
    out.append("# rebyte(x) is B.byte(x): both read x's low 8 bits")
    out.append("def rebyte_byte(+x: U32) -> {Bi.c842.rebyte(x) == B.byte(x) : U32}:")
    out.append("  match x:")
    out.append("    case %s:" % u32_pat(8, "hi"))
    out.append("      {==}")
    out.append("")
    out.append("# reword(x) is x: all 32 bits")
    out.append("def reword_id(+x: U32) -> {Bi.c842.reword(x) == x : U32}:")
    out.append("  match x:")
    out.append("    case %s:" % u32_pat(32, "WNil{}"))
    out.append("      {==}")
    return "\n".join(out)


def chunks():
    """lit_main's case tree: xs as 0 to 7 bytes, or 8 and more."""
    out = []
    names = ["b%d" % i for i in range(8)]
    st = "D.C842Going{acc, n, w, Nat.add(List.length(&2, U32, XS), k)}"
    def xs_of(i, tail):
        s = tail
        for j in range(i - 1, -1, -1):
            s = "Con{b%d, %s}" % (j, s)
        return s
    ind = "  "
    out.append(ind + "match xs:")
    for i in range(8):
        pad = ind + "  " * (2 * i)
        if i > 0:
            pass
        out.append(pad + "  case Nil{}:")
        out.append(pad + "    {==}")
        out.append(pad + "  case Con{b%d, t%d}:" % (i, i + 1))
        out.append(pad + "    match t%d:" % (i + 1))
    pad = ind + "  " * 16
    # t8 is the rest after 8 bytes: an induction step
    acc8 = "acc"
    n8 = "n"
    w8 = "w"
    for i in range(8):
        w8 = "W.c842.win.put(%s, %s, Bi.c842.rebyte(b%d))" % (w8, n8, i)
        acc8 = "Con{Bi.c842.rebyte(b%d), %s}" % (i, acc8)
        n8 = "U32.add(%s, 1)" % n8
    # the last match level was "match t8:" — replace with direct call on t8
    out[-1] = " " * 34 + "lit_main(t8, c, r, %s, %s, %s, k)" % (acc8, n8, w8)
    return "\n".join(out)


def groups():
    """unpack_group's and mask_group's partial cases: 1 to 7 bits."""
    out = []
    for name, goal in (("unpack_group", "{F.c842.unpack.list(F.c842.fmt.group(XS)) == F.c842.fmt.cat(XS, F.c842.fmt.zeros(F.c842.fmt.gfill(XS))) : List<&2, Bool>}"),
                       ("mask_group", "{B.mask(F.c842.fmt.group(XS)) == F.c842.fmt.group(XS) : List<&2, U32>}")):
        out.append("def %s(+bs: List<&2, Bool>) -> %s:" % (name, goal.replace("XS", "bs")))
        out.append("  match bs:")
        for i in range(8):
            pad = "  " + "  " * (2 * i)
            out.append(pad + "  case Nil{}:")
            out.append(pad + "    {==}")
            out.append(pad + "  case Con{c%d, t%d}:" % (i, i + 1))
            out.append(pad + "    match t%d:" % (i + 1))
        pad = "  " + "  " * 16
        xs = "t8"
        for j in range(7, -1, -1):
            xs = "Con{c%d, %s}" % (j, xs)
        if name == "unpack_group":
            rhs = "_"
            for j in range(7, -1, -1):
                rhs = "Con{c%d, %s}" % (j, rhs)
            p = "{F.c842.unpack.list(F.c842.fmt.group(%s)) == %s : List<&2, Bool>}" % (xs, rhs)
        else:
            p = "{B.mask(F.c842.fmt.group(%s)) == Con{Bi.c842.byte.of(c7, c6, c5, c4, c3, c2, c1, c0), _} : List<&2, U32>}" % xs
        out[-1] = " " * 34 + "%%%s(t8) : %s" % (name, p)
        out.append(" " * 34 + "{==}")
        out.append("")
    return "\n".join(out)


def lens():
    """lit_len's case tree: the literal stream's bits, counted."""
    out = []
    out.append("  match xs:")
    for i in range(8):
        pad = "  " + "  " * (2 * i)
        out.append(pad + "  case Nil{}:")
        out.append(pad + "    {==}")
        out.append(pad + "  case Con{b%d, t%d}:" % (i, i + 1))
        out.append(pad + "    match t%d:" % (i + 1))
    xs = "t8"
    for j in range(7, -1, -1):
        xs = "Con{b%d, %s}" % (j, xs)
    out[-1] = " " * 34 + "%%lit_len(t8, c) : {List.length(&2, Bool, F.c842.serialise(C.c842.enc.lits(%s, c))) == Nat.add(69n, _) : Nat}" % xs
    out.append(" " * 34 + "{==}")
    return "\n".join(out)


def starts():
    """The laws on streams that cannot start: the first byte (and the
    second, for RPT's field) split into bits, then the decoder fails and
    takes no more."""
    def u32(k, last, v="c"):
        s = last
        for i in range(k - 1, -1, -1):
            s = "WCon{%s%d, %s}" % (v, i, s)
        return "U32{%s}" % s

    def law(name, first, err, second=False):
        R = "Result<&2, &2, E.C842Error, B.Octets>"
        goal_tail = "== Fail{E.%s{}} : %s}" % (err, R)
        out = []
        if first == 232:
            X = "232"
            params = "rest, max"
        else:
            params = "lo, b, rest, max" if second else "lo, rest, max"
        out.append("def Laws.%s(%s):" % (name, params))
        ind = "  "
        if first != 232:
            out.append(ind + "match lo:")
            out.append(ind + "  case %s:" % u32(32, "WNil{}"))
            ind += "    "
            X = "U32.or(%d, U32.and(7, %s))" % (first, u32(32, "WNil{}"))
        if second:
            Bv = u32(8, "bh", "d")
            out.append(ind + "match b:")
            out.append(ind + "  case %s:" % Bv)
            ind += "    "
            inner = "B.Octets.cons(%s, rest)" % Bv
        else:
            inner = "rest"
        out.append(ind + "%%Equal.sym(List<&2, U32>, B.Octets.to_list(B.Octets.cons(%s, %s)), Con{B.byte(%s), B.Octets.to_list(%s)}, BL.octets_cons_list(%s, %s)) : {D.c842.dec.result(D.c842.dec.go(F.c842.unpack.list(_), D.c842.dec.start(max))) %s" % (X, inner, X, inner, X, inner, goal_tail))
        if second:
            out.append(ind + "%%Equal.sym(List<&2, U32>, B.Octets.to_list(%s), Con{B.byte(%s), B.Octets.to_list(rest)}, BL.octets_cons_list(%s, rest)) : {D.c842.dec.result(D.c842.dec.go(F.c842.unpack.list(Con{B.byte(%s), _}), D.c842.dec.start(max))) %s" % (inner, Bv, Bv, X, goal_tail))
        tl = "B.Octets.to_list(rest)"
        out.append(ind + "%%Equal.sym(D.C842Dec, D.c842.dec.go(F.c842.unpack.list(%s), D.C842Dec{F.c842.parse.code_next(), D.C842Failed{E.%s{}}}), D.C842Dec{F.c842.parse.code_next(), D.C842Failed{E.%s{}}}, absorb_fail(F.c842.unpack.list(%s), F.c842.parse.code_next(), E.%s{})) : {D.c842.dec.result(_) %s" % (tl, err, err, tl, err, goal_tail))
        out.append(ind + "{==}")
        return "\n".join(out)

    return "\n\n".join([law("code26_rejected", 208, "C842BadTemplate"),
                        law("code31_rejected", 248, "C842BadTemplate"),
                        law("repeat_first_rejected", 216, "C842BadRepeat", True),
                        law("short_zero_rejected", 232, "C842BadShort")]) + "\n"


print({"words": words, "chunks": chunks, "groups": groups, "lens": lens, "starts": starts}[sys.argv[1]]())
